"""Authentication, user-administration, and integration manuscript contracts."""
from api_contracts import P, DIRECTORY, add

add("GET", P+"/users", "Search the User Directory", DIRECTORY+" Optional page (>=1, default 1), pageSize (1–100, default 50).", "data: [{ id, name, email, image, role, isOutsideOrg, blocked, studentNumber, studentProfileId, department, yearLevel, joinedAt }], with list metadata", "The year defaults to active, otherwise newest. Academic year alone does not restrict account membership. Name/student-number sorting occurs within the page already selected by joined date, not globally. These endpoints do not require the integration step-up.")
add("PATCH", P+"/users", "Change Student or Officer Permissions in Bulk", "Body: userIds (required array, 0–500 nonempty identifiers), role (required permitted student/officer wire value).", "data: { updated, skipped: [...] }", "Only student-to-officer or officer-to-student changes are allowed. Human role labels are not accepted wire values; use the administrative account client for this request. Already-matching/unsupported targets are skipped; missing IDs are absent from the result. Empty selection succeeds with zero updates.")
add("DELETE", P+"/users", "Block or Delete Selected Accounts", "Body: userIds (required array, 0–500 nonempty identifiers).", "data: { hardDeleted: [...], blocked: [...], skipped: [{ userId, reason }] }", "Accounts with activity are blocked, their sessions revoked, and queue/availability state cleaned. Inactive accounts take the narrower delete path. Administrators, already-blocked accounts, and missing accounts are skipped. This is not the separate permanent-purge operation.", {"userIds":["user-example"]})
add("PATCH", P+"/users/:userId", "Change One Student or Officer Permission", "Path: userId. Body: role (required permitted student/officer wire value).", "data: { userId, role }", "Use the account-management client rather than substituting a human label. Other email-derived account categories cannot be changed through this action. Repeating the same allowed value is a no-op success.", errors="404 missing user; 409 unsupported current category; 403 attempted self-demotion.")
add("DELETE", P+"/users/:userId", "Permanently Purge a Blocked Account", "Path: userId.", "data: { userId }", "Permanent removal and related-record cleanup require an already-blocked non-administrator account.", errors="404 missing user; 403 administrator target; 409 target not blocked.")
add("POST", P+"/users/:userId/password-reset", "Set a Replacement Student Password", "Path: userId. Body: newPassword (required string, 8–128 characters).", "data: { success: true, message }", "Immediately sets credentials, not an emailed link. Only a student target other than the caller is allowed. This handler does not revoke existing target sessions or exclude blocked targets.", {"newPassword":"<new password chosen securely>"}, "404 missing user; 403 self/other account category; 400 invalid password.")

add("GET", P+"/integrations", "Read Integration Availability and Configuration", response="data: { flags, turnstileSiteKey, overridesLoaded } for public/non-administrator callers; data: integration rows for an administrator", notes="Administrator rows include key, label, description, enabled, configured, consequence, updatedByName/updatedAt, credentials, version, pendingRestart, overridesLoaded. Secret credential entries have value null and a mask; plain entries may expose values. Viewing does not require a step-up unlock. Enabling a service does not itself prove it is configured.")
add("GET", P+"/integrations/authenticators", "List Administrator Authenticator Status", response="data: [{ userId, name, email, enrolled }]", notes="Administrator session required; no step-up required merely to view status.")
add("DELETE", P+"/integrations/authenticators/:userId", "Reset an Administrator Authenticator", "Path: userId.", "data: { userId, enrolled: false }", "Requires a current administrator step-up unlock. Deletes the target's authenticator and temporary unlock and requires fresh setup. Self-reset is allowed.", errors="403 with data.code STEP_UP_REQUIRED while locked; 404 target absent/not administrator.")
add("GET", P+"/integrations/credentials/export", "Export Effective Integration Credentials", response="data: { filename, content }", notes="Requires a current step-up unlock. Cache-Control: no-store. Content contains actual effective secrets, not masks. Store privately and never paste the export into the manuscript, screenshots, or source control. Unreadable overrides can fall back to configured environment values.", errors="403 with data.code STEP_UP_REQUIRED while locked.")
add("PATCH", P+"/integrations/:key", "Enable or Disable an Integration", "Path: key is turnstile, r2, googleAuth, cloudflareChat, email, googleForms, or googleCalendar. Body: enabled (required boolean).", "data: { key, enabled }", "Requires current step-up. Does not verify that credentials exist merely to enable a switch.", {"enabled":True}, "404 unknown integration; 403 STEP_UP_REQUIRED.")
add("PUT", P+"/integrations/:key/credentials", "Save Integration Credential Overrides", "Path: key is a supported integration key. Body: version (required integer >=0), values (required object mapping allowed credential field names to strings up to 4,096 characters or null).", "data: updated integration row", "Requires current step-up. Omitted fields retain current overrides/fallbacks; null removes an override; empty strings are rejected. Required effective values, paired submissions, and supported provider probes are checked before saving. An all-null nonempty reset bypasses provider/required-value checks but still follows pairing rules. Unchanged saves do not increment version. Ten credential PUT/DELETE attempts per minute per administrator. Some saved values require restart; inspect pendingRestart.", {"version":0,"values":{"MAIL_FROM":"ERPSYS <no-reply@example.org>","BREVO_API_KEY":"<new provider credential>"}}, "400 unknown credential name/invalid body; 404 unknown integration; 403 STEP_UP_REQUIRED; 409 stale version or concurrent save; 422 with data.failures [{ key, reason }] for group/provider failure; 429 credential limit.")
add("DELETE", P+"/integrations/:key/credentials", "Restore Configured Credential Defaults", "Path: key is a supported integration key. No version business field.", "data: integration row", "Clears the group's saved overrides and falls back to configured environment values. It does not import a backup, restart the server, or change the service switch. Requires current step-up and shares the credential-write limit.", errors="403 STEP_UP_REQUIRED; 404 unknown key; 429 limit.")

AUTH_ENDPOINTS = [
("POST","/api/auth/sign-in/email","Sign In with Email and Password","Public","Body: email and password, required. Optional callbackURL and rememberMe. Supply a valid Turnstile token through cf-turnstile-response, turnstileToken, or the matching header when the configured auth check requires it.","Better Auth sign-in result with user/token information and session cookie","Credential requests share a 20-attempt IP budget per five minutes. Blocked users cannot create new sessions. This response is not a versioned data/ts envelope.",{"email":"student@example.org","password":"<account password>","turnstileToken":"<fresh challenge token>"},"400 invalid challenge/body; 401 invalid credentials; 403 blocked account; 429 repeated attempts."),
("POST","/api/auth/sign-up/student","Register a Student Account","Public","Body: name (nonempty), studentNumber (trimmed digits only), email (valid email), password (8–128 characters), academicYearId, departmentId, yearLevel (FIRST/SECOND/THIRD/FOURTH/FIFTH), required. Optional cf-turnstile-response or turnstileToken (1–2,048 characters).","{ token, user }, with session cookie; HTTP 200","Creates profile and placement and signs in. University student-email accounts use Google instead of this password-registration route. A blocked account owning the email/number can be replaced. The year must exist but need not be active. Placement errors currently may surface as generic 500 because of error adaptation, even for unsuitable course/year selections; do not promise every placement failure is a 400.",{"name":"Example Student","studentNumber":"202600001","email":"student@example.org","password":"<new password>","academicYearId":"year-example","departmentId":"department-example","yearLevel":"FIRST","turnstileToken":"<fresh challenge token>"},"400 malformed/duplicate identity or university email requiring Google; 429 credential-request budget; 500 possible placement/persistence failure."),
("POST","/api/auth/sign-up/email","Standard Password Signup Is Disabled","Public","Standard library signup is not the supported student-registration path.","No successful registration through this endpoint","Use the custom student signup route. An HTTP request here is deliberately rejected.",None,"400 rejected registration."),
("POST","/api/auth/sign-in/social","Begin Google Sign-In","Public","Body: provider: google; callbackURL for the permitted return destination. Other optional Better Auth redirect controls remain library-owned.","Better Auth provider authorization URL/redirect result; follow the configured flow","Google integration must be enabled. Do not treat this as a completed authenticated session before the provider callback succeeds.",{"provider":"google","callbackURL":"/"},"412 Google sign-in disabled; provider errors use the authentication response format."),
("GET","/api/auth/callback/google","Complete Google Sign-In","Public provider callback","Google supplies authorization code/state or error query parameters.","Authentication-library redirect and session handling","Validate the callback through the configured OAuth flow, not a hand-created code/state example. This callback is different from the optional calendar connection.",None,"OAuth state, code, account, or provider errors; redirects and library responses vary by outcome."),
("GET","/api/auth/get-session","Read the Current Sign-In Session","Public; session cookie identifies a signed-in account","No business body/query fields.","Session and user object, or null when signed out","Unwrapped authentication JSON, not data/ts. Session cookies are managed by the auth library.",None,"Authentication-library failures may occur."),
("POST","/api/auth/sign-out","Sign Out","Signed-in session for normal use","No business body fields.","Authentication-library success; clears session cookie","The application hook also closes the adviser's open availability, releases active service, and removes adviser department assignments. Do not describe sign-out as only a browser-local action.",None,"Library session/origin errors."),
("POST","/api/auth/request-password-reset","Request an Emailed Password-Reset Link","Public","Body: email (required valid email), redirectTo (optional, trusted-origin restrictions).","{ status: true, message } whether or not an account exists","The application sends a direct reset-page link with a one-hour token. A success response does not prove email delivery; production can log a delivery failure while still returning success. The current forgot-password screen directs users to staff rather than requesting this route itself. redirectTo does not alter the application's emailed destination.",{"email":"student@example.org"},"400 malformed email or disallowed redirect; normal responses do not disclose account existence."),
("POST","/api/auth/reset-password","Consume a Password-Reset Token","Public, authorized by reset token","Body: newPassword (required, 8–128 characters), token (body or query; one required; nonempty body value takes precedence).","{ status: true }","Consumes the token once. Creates password credentials if absent. The configured application does not revoke existing sessions after this reset.",{"token":"<token from reset email>","newPassword":"<new password>"},"400 invalid/expired/consumed token or password length."),
("GET","/api/auth/reset-password/:token","Library Password-Reset Callback","Public token callback","Path: token. Required query: callbackURL, subject to trusted-origin rules.","302 redirect carrying token, or error=INVALID_TOKEN","The library callback is available, but application reset emails link directly to the website reset page.",None,"Invalid callback/token produces a redirect error rather than a JSON success."),
("GET","/api/auth/admin-gate/status","Read Sensitive-Action Verification Status","Administrator session","No business body/query fields.","{ unlocked, unlockedUntil, next, enrolled }","next is pin/password/code/totp. Use unlocked to decide whether protected integration operations are available; next alone is not authorization.",None,"401 signed out; 403 not administrator."),
("POST","/api/auth/admin-gate/pin","Confirm the Administrator PIN","Administrator session","Body: pin, exactly six decimal digits.","{ ok: true }","Starts/restarts PIN → password → emailed code → authenticator verification. Passwordless accounts automatically satisfy the password step. PIN budgets: eight per user and sixty globally per fifteen minutes.",{"pin":"<six-digit administrator PIN>"},"400 malformed PIN; 403 incorrect; 429 budget exhausted; 503 PIN unconfigured."),
("POST","/api/auth/admin-gate/password","Confirm the Administrator Password","Administrator session","Body: password, 1–128 characters.","{ ok: true }","Requires fresh PIN. Skip for passwordless accounts rather than sending an empty password. Eight attempts per fifteen minutes per account.",{"password":"<administrator password>"},"403 STEP_ORDER; 400 invalid password; 429 limit."),
("POST","/api/auth/admin-gate/code/send","Send Administrator Confirmation Email","Administrator session","No business body fields.","{ ok: true }","Requires the fresh password step, including automatic passwordless satisfaction. Code freshness is ten minutes; wait sixty seconds before resending. Production delivery failure clears the chain.",None,"403 STEP_ORDER; 429 resend too soon; 503 production delivery failure."),
("POST","/api/auth/admin-gate/code/verify","Verify the Emailed Administrator Code","Administrator session","Body: code, exactly six decimal digits.","{ ok: true }","Five attempts per sent code; expired or consumed codes must be replaced. Auth ordering errors expose a STEP_ORDER code but do not preserve every service-level detail.",{"code":"<six-digit emailed code>"},"403 STEP_ORDER; 400 wrong, expired, absent, consumed, or exhausted code."),
("POST","/api/auth/two-factor/enable","Prepare Authenticator Enrollment","Administrator session after email-code verification","Body: password (schema-optional, required when the account has password credentials); issuer (optional, default ERPSYS).","{ totpURI, backupCodes }","Returns setup material and normally ten backup codes. Keep both private. Does not unlock integrations until final verification. Already-enrolled users must use authorized reset rather than re-enable.",None,"403 STEP_ORDER/already enrolled; 400 invalid required password."),
("POST","/api/auth/two-factor/verify-totp","Verify the Authenticator Code","Administrator session after email-code verification","Body: code (required string, six-digit 30-second authenticator code); trustDevice (optional, true rejected).","{ token, user }; may rotate the session cookie","First successful verification completes enrollment. Success unlocks protected integration actions for five minutes. This is step-up authorization, not a mandatory MFA sign-in redirect.",{"code":"<current authenticator code>"},"403 STEP_ORDER; 400 setup absent/trusted device requested; 401 invalid code; 429 after five shared authenticator/backup attempts, requiring restart from PIN."),
("POST","/api/auth/two-factor/verify-backup-code","Use a One-Time Authenticator Backup Code","Administrator session after email-code verification","Body: code (required); disableSession (optional boolean), trustDevice (optional; true rejected).","{ token, user }","Consumes one backup code and grants the five-minute unlock. It is not equivalent to completing pending authenticator enrollment. Other two-factor operations are forbidden by the application allowlist.",None,"400 backup setup absent; 401 invalid code; 403 STEP_ORDER; 409 concurrent use; 429 shared five-attempt chain budget.")
]
